import{reactive,ref}from"vue";import{defineStore}from"pinia";import{useCustomStore}from"./customStore";import axios from"axios";export const useRegisterStore=defineStore("register",()=>{const apiUrl=import.meta.env.VITE_APP_API_URL,customStore=useCustomStore(),isLoading=ref(!1),login=reactive({email:"",password:""}),register=reactive({name:"",address:"",phone_number:"",email:"",password:""}),loginHandler=async()=>{isLoading.value=!0;const formData=new FormData;formData.append("email",login.email),formData.append("password",login.password);const res=await axios.post(apiUrl+"/login",formData);if(customStore.toast(res.data.message,res.data.status),"error"===res.data.status)return isLoading.value=!1;for(const key in login)login[key]="";isLoading.value=!1},registerHandler=async()=>{isLoading.value=!0;const formData=new FormData;formData.append("name",register.name),formData.append("address",register.address),formData.append("phone_number",register.phone_number),formData.append("email",register.email),formData.append("password",register.password);const res=await axios.post(apiUrl+"/register",formData);if(customStore.toast(res.data.message,res.data.status),"error"===res.data.status)return isLoading.value=!1;for(const key in register)register[key]="";isLoading.value=!1};return{apiUrl:apiUrl,register:register,registerHandler:registerHandler,loginHandler:loginHandler,login:login,isLoading:isLoading}});